// builds the cube solver C++ TurboModule (shared/) and the rubiks-algorithm submodule
// (cpp/rubiks-algorithm) into the app. android/ and ios/ are generated by `expo prebuild`, so this
// does the native project steps from React Native's C++ TurboModule guide every time they are:
//
// android: a CMakeLists.txt in app/src/main/jni that adds the sources to the app's native library
// ios:     the sources added to the app target in the Xcode project
//
// the module registers itself with React Native once the app's native code has loaded (see
// shared/NativeCubeSolver.cpp), so nothing else in either project needs to change

const fs = require('fs');
const path = require('path');
const { IOSConfig, withAppBuildGradle, withDangerousMod, withXcodeProject } = require('expo/config-plugins');
const { mergeContents } = require('@expo/config-plugins/build/utils/generateCode');

const ALGORITHM_DIR = 'cpp/rubiks-algorithm';
const XCODE_GROUP = 'CubeSolver';

// every .cpp to build, relative to the project root. main.cpp is the submodule's own test program
function getSources(projectRoot) {
  const algorithmDir = path.join(projectRoot, ALGORITHM_DIR);
  const algorithm = fs.existsSync(algorithmDir)
    ? fs.readdirSync(algorithmDir).filter((file) => file.endsWith('.cpp') && file !== 'main.cpp')
    : [];

  if (algorithm.length === 0) {
    throw new Error(`${ALGORITHM_DIR} is empty, run \`git submodule update --init\` first`);
  }

  return ['shared/NativeCubeSolver.cpp', ...algorithm.sort().map((file) => `${ALGORITHM_DIR}/${file}`)];
}

function relativePath(from, projectRoot, file) {
  return path.relative(from, path.join(projectRoot, file)).replace(/\\/g, '/');
}

const withCubeSolverAndroid = (config) => {
  config = withDangerousMod(config, [
    'android',
    (config) => {
      const { projectRoot, platformProjectRoot } = config.modRequest;
      const jniDir = path.join(platformProjectRoot, 'app/src/main/jni');
      const sources = getSources(projectRoot).map((file) => `  ${relativePath(jniDir, projectRoot, file)}`);

      // the same as React Native's default (ReactAndroid/cmake-utils/default-app-setup/CMakeLists.txt),
      // plus the solver's sources. with no .cpp files in this folder, React Native's default OnLoad.cpp is used
      const cmakeLists = [
        '# generated by plugins/with-cube-solver.js, changes here are lost on the next prebuild',
        'cmake_minimum_required(VERSION 3.13)',
        '',
        'project(appmodules)',
        '',
        'include(${REACT_ANDROID_DIR}/cmake-utils/ReactNative-application.cmake)',
        '',
        'target_sources(${CMAKE_PROJECT_NAME} PRIVATE',
        ...sources,
        ')',
        '',
      ].join('\n');

      fs.mkdirSync(jniDir, { recursive: true });
      fs.writeFileSync(path.join(jniDir, 'CMakeLists.txt'), cmakeLists);

      return config;
    },
  ]);

  return withAppBuildGradle(config, (config) => {
    config.modResults.contents = mergeContents({
      tag: 'cube-solver',
      src: config.modResults.contents,
      newSrc: [
        '    externalNativeBuild {',
        '        cmake {',
        '            path "src/main/jni/CMakeLists.txt"',
        '        }',
        '    }',
      ].join('\n'),
      anchor: /^android\s*\{/,
      offset: 1,
      comment: '//',
    }).contents;

    return config;
  });
};

const withCubeSolverIos = (config) =>
  withXcodeProject(config, (config) => {
    const { projectRoot, platformProjectRoot } = config.modRequest;
    const project = config.modResults;

    // file paths in a top level group are relative to the ios folder
    IOSConfig.XcodeUtils.ensureGroupRecursively(project, XCODE_GROUP);
    const group = project.findPBXGroupKey({ name: XCODE_GROUP });
    const target = project.getTarget('com.apple.product-type.application').uuid;

    for (const source of getSources(projectRoot)) {
      // the xcode package doesn't know .cpp files, so the type and encoding (UTF-8) are given.
      // null if it's already added
      const file = project.addFile(relativePath(platformProjectRoot, projectRoot, source), group, {
        lastKnownFileType: 'sourcecode.cpp.cpp',
        defaultEncoding: 4,
      });

      if (file) {
        file.group = 'Sources';
        file.target = target;
        file.uuid = project.generateUuid();
        project.addToPbxBuildFileSection(file);
        project.addToPbxSourcesBuildPhase(file);
      }
    }

    return config;
  });

module.exports = (config) => withCubeSolverIos(withCubeSolverAndroid(config));
